import {FISH} from './model.js';import {remainingFish} from '../state/fishing.js';import {SLOTS,ITEM_LABELS} from '../world/rooms.js';import {initialFishCooking,reduceFishCooking,fishCookingCompletion,FISH_HEAT} from './cooking-model.js';import {createFishCookingView} from './cooking-view.js';
const BODY=`<div class="fish-cook-layout"><div id="fish-cook-court" role="img" aria-label="직접 물고기를 손질하고 굽는 도름이"></div><section id="fish-cook-panel"><p id="fish-cook-status" role="status" aria-live="polite"></p><div id="fish-cook-options" class="fish-cook-options"></div><section id="fish-cook-recipe" hidden><p id="fish-cook-stock"></p><button id="fish-cook-prepare" data-fish-cook-action="prepare" class="primary"></button><div id="fish-cook-heat" hidden><p>양쪽을 초록 구간까지 구워요</p><label>첫 번째 면 <meter id="fish-cook-side-0" min="0" max="18" low="8" high="14" optimum="11"></meter></label><label>두 번째 면 <meter id="fish-cook-side-1" min="0" max="18" low="8" high="14" optimum="11"></meter></label><p id="fish-cook-heat-note"></p><div class="choice-row">${[1,2,3].map((n,i)=>`<button data-fish-cook-action="level" data-level="${n}">${['약불','중불','센불'][i]}</button>`).join('')}</div><div class="choice-row"><button id="fish-cook-resume" data-fish-cook-action="resume">가열 시작</button><button data-fish-cook-action="pause">불 끄고 쉬기</button><button id="fish-cook-flip" data-fish-cook-action="flip">뒤집기</button><button data-fish-cook-action="finish">다 구웠어요</button></div></div><button id="fish-cook-complete" data-fish-cook-action="complete" class="primary" hidden></button><p id="fish-cook-result" role="status" aria-live="polite"></p><section id="fish-cook-placement" hidden><h3>집에 놓을 자리</h3><div class="choice-row">${Object.entries(SLOTS).map(([id,s])=>`<button data-fish-cook-action="slot" data-slot="${id}">${s.label}</button>`).join('')}</div><p id="fish-cook-place-note"></p><button id="fish-cook-place" data-fish-cook-action="place">이 자리에 놓기</button></section><button data-fish-cook-action="reset">물고기 다시 고르기</button></section><p class="caption">완성할 때만 한 마리를 써요. 실패하거나 완성 전에 나가면 물고기는 그대로예요. 게임 속 요리 모형이며 실제 조리 온도·시간 안내가 아니에요.</p></section></div>`;
export function createFishCookingController({ui,getProgress,transact,canSave=()=>true,getRoom,getView,getActors,stage,onActive=()=>{},reduced=false,doc=globalThis.document,win=globalThis.window,createView=createFishCookingView}){
 let live=null;const $=id=>doc.querySelector('#'+id),listen=(s,n,t,f)=>{n.addEventListener(t,f);s.listeners.push([n,t,f]);};
 function close(token=live){if(!live||live!==token)return;const s=live;live=null;for(const[n,t,f]of s.listeners)n.removeEventListener(t,f);s.view?.dispose();doc.body.classList.remove('fish-cooking-open');stage.classList.remove('fish-cooking-open');onActive(false);}
 function render(s){if(live!==s)return;const p=getProgress(),a=s.state,phase=a?.phase,fish=a?FISH[a.fishId]:null,owned=!!a&&p.ownedItemIds.includes('fish-platter-'+a.fishId);let status=!canSave()?'이 탭은 둘러보기 모드예요. 요리와 배치를 저장하지 않아요':!a?'잡아 온 물고기를 골라요':phase==='prepare'?`${a.step+1}/3 · ${['깨끗이 손질하기','간하기','팬에 올리기'][a.step]}`:phase==='heat'?a.running?'색이 변해요 · 뒤집을 때를 골라요':'불을 껐어요 · 직접 가열을 이어가요':phase==='ready'?'양쪽이 노릇해요! 마지막으로 완성해요':phase==='failed'?(a.reason==='burned'?'너무 오래 구웠어요':a.reason==='overdone'?'조금 과하게 구웠어요':'속까지 익도록 양쪽을 더 구워 봐요')+' · 물고기는 쓰지 않았어요':s.mode==='camp'?(a.mealElapsed<2.7?'따뜻한 생선구이를 먹어요':'따뜻한 생선구이를 먹었어요'):'완성 접시를 보관했어요';if(s.status!==status){$('fish-cook-status').textContent=status;s.status=status;}
  $('fish-cook-options').hidden=!!a;const optionKey=[s.mode,...Object.keys(FISH).flatMap(id=>[p.fishing.counts[id],remainingFish(p.fishing,id),p.ownedItemIds.includes('fish-platter-'+id)])].join('|');if(s.optionKey!==optionKey){s.optionKey=optionKey;$('fish-cook-options').innerHTML=Object.entries(FISH).map(([id,f])=>{const known=p.fishing.counts[id]>0,kept=p.ownedItemIds.includes('fish-platter-'+id),n=remainingFish(p.fishing,id);return `<button data-fish-cook-action="choose" data-fish="${id}"${n===0&&!(s.mode==='home'&&kept)?' disabled':''}><img src="fishing/guide/${id}.webp" alt="" class="${known?'':'unknown'}"><strong>${known?f.label:'아직 만나지 못했어요'}</strong><span>${kept&&s.mode==='home'?'완성 접시 배치하기':n+'마리 보관'}</span></button>`;}).join('');}$('fish-cook-recipe').hidden=!a;if(!a){s.view?.update(null);return;}
  $('fish-cook-stock').textContent=`${fish.label} · ${remainingFish(p.fishing,a.fishId)}마리 보관 · 지금까지 ${p.fishing.counts[a.fishId]}마리 발견`;$('fish-cook-prepare').hidden=phase!=='prepare';$('fish-cook-prepare').textContent=a.busy?'도름이가 준비하는 중…':['손질하기','간하기','팬에 올리기'][a.step]??'';$('fish-cook-prepare').disabled=a.busy||s.paused||!canSave();$('fish-cook-heat').hidden=phase!=='heat';for(let i=0;i<2;i++)$('fish-cook-side-'+i).value=a.sides[i];$('fish-cook-heat-note').textContent=`첫 면 ${a.sides[0].toFixed(1)} · 둘째 면 ${a.sides[1].toFixed(1)} / 초록 ${FISH_HEAT.ready}–${FISH_HEAT.upper}칸 · 지금 ${a.side+1}번째 면`;$('fish-cook-resume').disabled=a.running||s.paused||!canSave();$('fish-cook-flip').disabled=a.sides[a.side]===0||!canSave();for(const b of s.root.querySelectorAll('[data-fish-cook-action="level"]'))b.setAttribute('aria-pressed',String(Number(b.dataset.level)===a.level));$('fish-cook-complete').hidden=phase!=='ready';$('fish-cook-complete').disabled=!canSave();$('fish-cook-complete').textContent=s.mode==='camp'?'완성해서 먹기 · 한 마리 사용':'접시로 간직하기 · 한 마리 사용';$('fish-cook-placement').hidden=!(phase==='complete'&&s.mode==='home'&&owned);
  const itemId='fish-platter-'+a.fishId,old=s.slot?p.placements[s.slot]:null;$('fish-cook-place-note').textContent=!s.slot?'놓을 자리를 직접 골라 주세요':old===itemId?'이미 이 자리에 놓여 있어요':old?`${ITEM_LABELS[old]}은 보관함으로 돌려놓고 바꿔요`:SLOTS[s.slot].label+'에 놓아요';$('fish-cook-place').disabled=!s.slot||!owned||old===itemId||!canSave();s.view?.update(a);
 }
 function open(mode='home'){if(live)return false;if(!['home','camp'].includes(mode)||getRoom()!==(mode==='home'?'homeKitchen':'courtyard')||!getView()?.root)return false;return ui.workshop(mode==='home'?'도름이의 생선 요리':'캠핑 생선구이',BODY,()=>{const s={mode,state:null,slot:null,root:$('fish-cook-panel'),listeners:[],paused:false,view:null,fit:null};live=s;doc.body.classList.add('fish-cooking-open');stage.classList.add('fish-cooking-open');onActive(true);try{s.view=createView({...getActors(),zoneRoot:getView().root,visual:getView().homeView,reduced,mode});}catch{close(s);ui.close?.();ui.toast?.('요리 자리를 준비하지 못했어요. 물고기는 그대로예요');return()=>{};}
  listen(s,s.root,'click',e=>{const b=e.target.closest?.('[data-fish-cook-action]');if(live!==s||!b||!s.root.contains(b)||b.disabled||doc.hidden)return;const action=b.dataset.fishCookAction,p=getProgress();if(action==='choose'){const id=b.dataset.fish;if(!Object.hasOwn(FISH,id)||remainingFish(p.fishing,id)<1&&!(mode==='home'&&p.ownedItemIds.includes('fish-platter-'+id)))return;s.state=initialFishCooking(id,p.fishing.consumed[id],{mode:mode==='camp'?'meal':'keepsake'});if(mode==='home'&&p.ownedItemIds.includes('fish-platter-'+id))s.state={...s.state,phase:'complete'};$('fish-cook-result').textContent='';render(s);return;}if(action==='reset'){s.state=null;s.slot=null;$('fish-cook-result').textContent='';render(s);return;}if(!s.state)return;if(action==='slot'){if(Object.hasOwn(SLOTS,b.dataset.slot))s.slot=b.dataset.slot;render(s);return;}if(!canSave()||s.paused)return;
   if(action==='complete'){const a=fishCookingCompletion(s.state);if(a){const ok=transact(a);if(ok)s.state={...s.state,phase:'complete',mealElapsed:0};$('fish-cook-result').textContent=ok?mode==='camp'?'완성했어요! 도름이가 한 입 먹어요. 낚시 기록은 그대로 남아요':'완성했어요! 집에 놓을 자리를 골라요':'저장하지 못해서 물고기는 쓰지 않았어요. 다시 완성을 눌러 주세요';}}
   else if(action==='place'&&s.slot&&s.state.phase==='complete'&&mode==='home'){const ok=transact({type:'PLACE_ITEM',slotId:s.slot,itemId:'fish-platter-'+s.state.fishId});$('fish-cook-result').textContent=ok?'집에 접시를 놓았어요':'저장하지 못해 배치를 바꾸지 않았어요';}
   else s.state=reduceFishCooking(s.state,{type:action.toUpperCase(),level:Number(b.dataset.level)});render(s);
  });
  const pause=()=>{if(live!==s)return;s.paused=true;if(s.state)s.state=reduceFishCooking(s.state,{type:'PAUSE'});render(s);};listen(s,win,'blur',pause);listen(s,win,'focus',()=>{if(live===s&&!doc.hidden){s.paused=false;render(s);}});listen(s,doc,'visibilitychange',()=>{if(doc.hidden)pause();else if(live===s){s.paused=false;render(s);}});listen(s,s.root,'keydown',e=>{if(e.repeat&&['Enter','Space'].includes(e.code))e.preventDefault();});render(s);return()=>close(s);
 },{kind:'fish-cooking-workshop',closeLabel:'나가기'});}
 return {open,cancel:()=>close(),close:()=>close(),get active(){return !!live;},get camera(){return live?.view?.camera;},snapshot:()=>live?.state?{...live.state,sides:[...live.state.sides],paused:live.paused}:null,tick(dt){const s=live;if(!s||s.paused||doc.hidden)return;if(s.state){if(!canSave())s.state=reduceFishCooking(s.state,{type:'PAUSE'});else if(s.state.phase==='complete'&&s.state.mode==='meal')s.state={...s.state,mealElapsed:Math.min(2.7,(s.state.mealElapsed??0)+Math.min(.1,Math.max(0,dt)))};else s.state=reduceFishCooking(s.state,{type:'TICK',dt});render(s);}s.view?.tick(dt);},viewport(width,height){if(!live)return {x:0,y:0,width,height};const b=$('fish-cook-court').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,b.left-base.left),y=Math.max(0,b.top-base.top),r={x,y,width:Math.max(1,Math.min(b.width,width-x)),height:Math.max(1,Math.min(b.height,height-y))},key=JSON.stringify(r);if(key!==live.fit){live.fit=key;live.view.fit(r.width,r.height);}return r;}};
}
